from fractions import Fraction as F
import json
import math


def exact_sqrt(v):
    # Exact rational square root; None if v is not a perfect rational square.
    if v < 0:
        return None
    n, d = v.numerator, v.denominator
    rn, rd = math.isqrt(n), math.isqrt(d)
    if rn * rn != n or rd * rd != d:
        return None
    return F(rn, rd)


def solve(a):
    # Given: a*x^2 + b*x + c <= 0 exactly when x <= -1 or x >= 3.
    # Roots are -1 and 3, so by Vieta a*(x+1)(x-3) = a*x^2 - 2a*x - 3a.
    r1, r2 = F(-1), F(3)
    b = -a * (r1 + r2)
    c = a * r1 * r2

    f = lambda x: a * x * x + b * x + c
    g = lambda x: c * x * x - b * x + a  # the target quadratic

    grid = [F(k, 12) for k in range(-60, 61)]
    orig_ok = all((f(x) <= 0) == (x <= -1 or x >= 3) for x in grid)

    p, q, r = c, -b, a  # g(x) = p*x^2 + q*x + r
    disc = q * q - 4 * p * r
    sq = exact_sqrt(disc)
    if sq is None or p <= 0 or not orig_ok:
        return None

    lo, hi = sorted([(-q - sq) / (2 * p), (-q + sq) / (2 * p)])
    # p > 0 means g < 0 strictly between its roots.
    interval_ok = all((g(x) < 0) == (lo < x < hi) for x in grid)
    if not interval_ok:
        return None

    return {"a": str(a), "b": str(b), "c": str(c),
            "roots": [str(lo), str(hi)]}


results = {}
for a in [F(-1), F(-2), F(-1, 2)]:
    results[str(a)] = solve(a)

valid = [v for v in results.values() if v is not None]
consistent = len(valid) == 3 and all(v["roots"] == valid[0]["roots"] for v in valid)

if consistent:
    lo, hi = valid[0]["roots"]
    final_answer = "{x | " + lo + " < x < " + hi + "}"
    print(json.dumps({
        "final_answer": final_answer,
        "evidence": {"a_scaling_invariant": True, "cases": results}
    }))
else:
    print("UNSUPPORTED")
