# Original equation: (7/4 - 2cos2x)*|2cos2x + 1| = cos x (cos x - cos 5x)
def f(x):
    c2 = math.cos(2 * x)
    c = math.cos(x)
    return (1.75 - 2 * c2) * abs(2 * c2 + 1) - c * (c - math.cos(5 * x))

# With t = cos2x, the RHS reduces to 1 + 2t - t^2 - 2t^3.
# Branch 2t+1 >= 0: 4*(LHS-RHS) = 8t^3 - 12t^2 - 2t + 3
# Branch 2t+1 <  0: 4*(LHS-RHS) = 8t^3 + 20t^2 - 14t - 11
def P_pos(t):
    return 8 * t**3 - 12 * t**2 - 2 * t + 3

def P_neg(t):
    return 8 * t**3 + 20 * t**2 - 14 * t - 11

def find_roots(P, lo, hi, n=4000):
    xs = [lo + (hi - lo) * i / n for i in range(n + 1)]
    rs = []
    for a, b in zip(xs, xs[1:]):
        fa, fb = P(a), P(b)
        if fa == 0:
            rs.append(a)
        elif fa * fb < 0:
            for _ in range(100):
                m = (a + b) / 2
                if P(a) * P(m) <= 0:
                    b = m
                else:
                    a = m
            rs.append((a + b) / 2)
    return rs

# Candidate t values from each branch, restricted to the branch domain and [-1, 1]
cands = []
for t in find_roots(P_pos, -0.5, 1.0):
    if -0.5 <= t <= 1.0:
        cands.append(t)
for t in find_roots(P_neg, -1.0, -0.5):
    if -1.0 <= t <= -0.5:
        cands.append(t)

# Deduplicate t values
t_vals = sorted({round(t, 9) for t in cands})

# Map each t to x in [0, pi): 2x = ±arccos(t) + 2πk
x_sols = []
for t in t_vals:
    theta = math.acos(max(-1.0, min(1.0, t)))
    for x in (theta / 2, math.pi - theta / 2):
        x = x % math.pi
        if abs(f(x)) < 1e-9:
            x_sols.append(x)

# Exact residues of x/π modulo 1
residues = sorted({Fr(x / math.pi).limit_denominator(60) % 1 for x in x_sols})

# Independent grid check over one period [0, π) for extra near-zero minima of |f|
N = 200000
grid = [math.pi * i / N for i in range(N)]
absf = [abs(f(x)) for x in grid]
minima = []
for i in range(1, N - 1):
    if absf[i] < 1e-3 and absf[i] <= absf[i - 1] and absf[i] <= absf[i + 1]:
        minima.append(grid[i])

def near_predicted(x):
    for r in residues:
        d = abs(((x - float(r) * math.pi) + math.pi / 2) % math.pi - math.pi / 2)
        if d < 2e-3:
            return True
    return False

unmatched = [x for x in minima if not near_predicted(x)]

res_strs = [str(r) for r in residues]
final_answer = (
    "x = nπ + aπ, n ∈ Z, a ∈ {" + ", ".join(res_strs) + "}"
    " (i.e. x = ±π/6 + nπ or x = ±π/3 + nπ)"
)

result = {
